{
  "core_question": "How should a 12-hospital health system design a defensible first version of an AI sepsis risk score clinical decision support tool across clinical safety, legal/regulatory exposure, and financial structure?",
  "rationale": "The question spans patient safety validation (healthcare), regulatory/contractual/legal risks (legal), and cost/ROI modeling for subscription pricing (finance).",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What clinical safety considerations, data quality requirements, model validation steps, and post-deployment monitoring processes should the health system implement to ensure that an AI sepsis risk score CDS tool meets standard of care and protects patient safety before it is rolled out across its 12 hospitals?",
    "legal": "What legal and regulatory exposures must the health system address when deploying a per-seat subscription AI CDS tool that surfaces sepsis risk scores, including FDA device classification, compliance with HIPAA and other privacy laws, liability for clinical decisions influenced by the tool, and contractual obligations with the vendor?",
    "finance": "How should the health system structure the financial model for a per-seat annual subscription AI CDS tool across 12 hospitals to balance upfront costs, ongoing maintenance fees, potential cost savings from improved sepsis outcomes, ROI expectations, and risk-sharing mechanisms?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Recent FDA guidance on AI/ML‑based SaMD (2024), evolving CMS reimbursement policies for CDS tools, and updates to data privacy regulations may affect the answers."
}
